from pwn import *
import time

# Connect to the server
def connect_server():
    return remote('misc.chal.csaw.io', 3001)

# Query a point and get classification
def query_point(conn, x, y):
    try:
        query = f"{x:.4f} {y:.4f}"
        conn.sendline(query.encode())
        response = conn.recvline().decode().strip()
        return response == "Cool!"
    except:
        conn.close()
        time.sleep(1)  # Add delay on error
        conn = connect_server()
        return query_point(conn, x, y)

# Binary search between two points
def binary_search(conn, p1, p2, precision=0.0001):
    x1, y1 = p1
    x2, y2 = p2
    c1 = query_point(conn, x1, y1)

    while abs(x1 - x2) > precision or abs(y1 - y2) > precision:
        mx = (x1 + x2) / 2
        my = (y1 + y2) / 2

        # Query midpoint
        mid_class = query_point(conn, mx, my)

        # Update endpoints based on classification
        if mid_class == c1:
            x1, y1 = mx, my
        else:
            x2, y2 = mx, my

        # Print current boundary point
        print(f"Current boundary point: ({(x1 + x2)/2:.4f}, {(y1 + y2)/2:.4f})")

    return (x1 + x2) / 2, (y1 + y2) / 2

def test_grid_point(conn, x, y):
    current = query_point(conn, x, y)

    # Check neighboring points
    offsets = [(0.5, 0), (0, 0.5), (-0.5, 0), (0, -0.5)]
    for dx, dy in offsets:
        nx, ny = x + dx, y + dy
        neighbor = query_point(conn, nx, ny)

        # If classification changes, found boundary
        if current != neighbor:
            return binary_search(conn, (x, y), (nx, ny))
    return None

def main():
    conn = connect_server()
    print("Connected to server")
    boundary_points = []

    # Test grid points systematically
    for x in range(-10, 11, 2):
        for y in range(-10, 11, 2):
            point = test_grid_point(conn, x, y)
            if point:
                boundary_points.append(point)
                print(f"Found boundary point: ({point[0]:.4f}, {point[1]:.4f})")

                if len(boundary_points) >= 5:
                    break
        if len(boundary_points) >= 5:
            break

    # Print final results
    print("\nFinal boundary points found:")
    for x, y in boundary_points:
        print(f"({x:.4f}, {y:.4f})")

    conn.close()

if __name__ == "__main__":
    main()
